+    private void configureFileNames(Properties properties) {
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (strategyWasGivenToConstructor) {
+            if (configured != null) {
+                throw new StoreInitializationFailedException(String.format(
