+        if (!folderExists) {
+            if (integrityMode == IntegrityMode.FAIL) {
+                // fail is read-only. A missing folder is the empty folder for the purpose of the check.
+                state.folderReal = null;
+            } else {
+                createFolder(folder);
+                folderIsDirectory = true;
+            }
+        } else if (!folderIsDirectory) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Violation store path is not a directory: %s", state.folder.getAbsolutePath()));
+        }
+
+        boolean indexExists = Files.exists(index, LinkOption.NOFOLLOW_LINKS);
+        if (indexExists && !isRegularFileDirect(index, folder)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "The index %s is not a regular file directly in the store folder", index.toAbsolutePath()));
