+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        state.folderReal = folderIsDirectory ? realPath(folder) : null;
+        state.indexPresent = indexExists;
+        state.properties = indexExists ? loadRulesFrom(state.index) : new Properties();
+
+        if (integrityMode == IntegrityMode.IGNORE) {
+            if (!indexExists) {
+                // Ignore is allowed to create the index as part of normal initialization.
+                createIndex(state);
+            }
+            return;
+        }
