+        repair(state, report);
+    }
+
+    private void createFolder(Path folder) {
+        try {
+            Files.createDirectories(folder);
+            if (!Files.isDirectory(folder)) {
+                throw new IOException("not a directory");
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot create violation store folder %s", folder.toAbsolutePath()), e);
+        }
+    }
+
+    private void createIndex(StoreState state) {
+        try {
+            if (!Files.exists(state.folder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                createFolder(state.folder.toPath());
+            }
+            if (!Files.exists(state.index.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                Files.createFile(state.index.toPath());
+            }
+            if (!isRegularFileDirect(state.index.toPath(), state.folder.toPath())) {
+                throw new IOException("index is not a regular file directly in the folder");
+            }
+            state.indexPresent = true;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot create rule store at %s", state.index.getAbsolutePath()), e);
+        }
+    }
+
+    private Properties loadRulesFrom(Path file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file.toFile())) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
