+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        checkNotNull(rule, "rule");
+        checkNotNull(violations, "violations");
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (stateLock()) {
+            saveLocked(rule.getDescription(), violations);
+        }
+    }
+
+    private void saveLocked(String description, List<String> violations) {
+        Entry existing = findEntry(description);
+        if (existing == null && integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+            return;
+        }
+
+        if (existing == null) {
+            String name = nameForNewRule(description);
+            validateNewSaveTarget(name, description);
+            ensureFolderForSave();
+            boolean wroteFile = false;
+            try {
+                write(violations, resolvePath(name));
+                wroteFile = true;
+                storeState.properties.setProperty(description, name);
+                syncIndex(storeState);
+            } catch (RuntimeException e) {
+                storeState.properties.remove(description);
+                if (wroteFile) {
+                    deleteQuietly(resolvePath(name));
+                }
+                throw e;
+            }
+            log.trace("Assigning new file {} to rule '{}'", name, description);
+            return;
+        }
+
+        if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+            forgetKnownRule(existing);
+            return;
+        }
+
+        validateExistingSaveTarget(existing);
+        write(violations, existing.path);
+    }
+
+    private String nameForNewRule(String description) {
+        String name;
+        if (fileNameMode == FileNameMode.RANDOM) {
+            name = UUID.randomUUID().toString();
+        } else if (fileNameMode == FileNameMode.DESCRIPTION) {
+            name = descriptionBasedName(description);
+        } else {
+            name = configuredStrategy.createRuleFileName(description);
+        }
+        return requireNameForSave(name, description);
+    }
+
+    private String expectedName(String description) {
+        if (fileNameMode == FileNameMode.RANDOM) {
+            return null;
+        }
+        String name = fileNameMode == FileNameMode.DESCRIPTION
+                ? descriptionBasedName(description)
+                : configuredStrategy.createRuleFileName(description);
+        return requireNameForInitialization(name, description);
+    }
+
+    private String descriptionBasedName(String description) {
+        String normalized = ensureUnixLineBreaks(description);
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(normalized);
+        String selectedWord = null;
+        while (matcher.find()) {
+            String word = matcher.group(1);
+            if (selectedWord == null || word.length() > selectedWord.length()) {
+                selectedWord = word;
+            }
+        }
+        if (selectedWord == null) {
+            selectedWord = "rule";
+        }
+        return selectedWord + "-" + sha256(normalized);
+    }
+
+    private String sha256(String value) {
+        try {
+            MessageDigest digest = MessageDigest.getInstance("SHA-256");
+            byte[] bytes = digest.digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(bytes.length * 2);
+            for (byte b : bytes) {
+                result.append(String.format("%02x", b & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new AssertionError(e);
+        }
+    }
+
+    private String requireNameForSave(String name, String description) {
+        if (name == null || name.isEmpty()) {
+            throw new StoreUpdateFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return name;
+    }
+
+    private String requireNameForInitialization(String name, String description) {
+        if (name == null || name.isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return name;
+    }
+
+    private void validateNewSaveTarget(String name, String description) {
+        Path path = resolvePathForSave(name, description);
+        if (isIndexTarget(path) || STORED_RULES_FILE_NAME.equals(path.getFileName().toString())) {
+            throw invalidSaveTarget(name, description, "the index");
+        }
+        if (!isDirectDestination(path)) {
+            throw invalidSaveTarget(name, description, "outside the store folder");
+        }
+        if (Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+            throw invalidSaveTarget(name, description, "already names something");
+        }
+        for (Entry entry : entries()) {
+            if (name.equals(entry.fileName)) {
+                throw invalidSaveTarget(name, description, "is already recorded by another entry");
+            }
+        }
+    }
+
+    private void validateExistingSaveTarget(Entry entry) {
+        if (isIndexTarget(entry.path) || !isDirectDestination(entry.path)
+                || (Files.exists(entry.path, LinkOption.NOFOLLOW_LINKS) && !Files.isRegularFile(entry.path))) {
+            throw invalidSaveTarget(entry.fileName, entry.ruleDescription, "does not lead to a writable file directly in the store folder");
+        }
+    }
+
+    private StoreUpdateFailedException invalidSaveTarget(String name, String description, String reason) {
+        return new StoreUpdateFailedException(String.format(
+                "Cannot store violations for rule '%s' in file '%s': %s", description, name, reason));
+    }
+
+    private Path resolvePathForSave(String name, String description) {
+        try {
+            return resolvePath(name);
+        } catch (InvalidPathException e) {
+            throw invalidSaveTarget(name, description, "the name is not a valid path");
+        }
+    }
+
+    private Path resolvePath(String name) {
+        return storeState.folder.toPath().resolve(name);
+    }
+
+    private void ensureFolderForSave() {
+        if (!Files.isDirectory(storeState.folder.toPath())) {
+            createFolder(storeState.folder.toPath());
+        }
+    }
+
+    private void forgetKnownRule(Entry entry) {
+        List<Entry> remaining = entries();
+        remaining.remove(entry);
+        if (!sharesFileWith(entry, remaining)) {
+            deleteFileAndLink(entry.path);
+        }
+        storeState.properties.remove(entry.ruleDescription);
+        syncIndex(storeState);
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetails, builder.toString().getBytes(UTF_8),
+                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (stateLock()) {
+            Entry entry = findEntry(rule.getDescription());
+            checkArgument(entry != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(entry.path);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(Path file) {
+        String violationsText = readStoreFile(file);
+        if (onlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(ensureUnixLineBreaks(violationsText))
+                .map(this::unescape)
+                .collect(toList());
+    }
+
