    private static class IntegrityReport {
        private final List<Entry> entries = new ArrayList<>();
        private final List<String> unownedFiles = new ArrayList<>();

        private boolean hasProblems() {
            return !unownedFiles.isEmpty() || entries.stream().anyMatch(entry ->
                    entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied);
        }

        private String message(StoreState state) {
            StringBuilder result = new StringBuilder("Cannot initialize violation store due to integrity problems");
            appendEntries(result, "broken entries", entry -> entry.broken);
            appendEntries(result, "resolved entries", entry -> entry.resolved);
            appendEntries(result, "shared entries", entry -> entry.shared);
            appendFiles(result, "unowned files");
            appendEntries(result, "misplaced entries", entry -> entry.misplaced);
            appendEntries(result, "colliding entries", entry -> entry.colliding);
            appendEntries(result, "occupied entries", entry -> entry.occupied);
            return result.toString();
        }

        private void appendEntries(StringBuilder result, String title, EntryPredicate predicate) {
            List<Entry> matching = entries.stream().filter(predicate::test)
                    .sorted(Comparator.comparing(entry -> entry.ruleDescription))
                    .collect(toList());
            if (!matching.isEmpty()) {
                result.append("\n").append(title).append(":");
                for (Entry entry : matching) {
                    result.append("\n  ").append(entry.ruleDescription).append(" -> ").append(entry.fileName);
