    private void moveToDerived(Entry entry) {
        Path destination = tryResolvePath(entry.expectedName);
        if (destination == null || !isDirectDestination(destination)) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot move violation file for rule '%s' to '%s'", entry.ruleDescription, entry.expectedName));
