            throw new StoreInitializationFailedException(String.format(
                    "Cannot move violation file for rule '%s' to '%s'", entry.ruleDescription, entry.expectedName), e);
        }
    }

    private boolean sharesFileWith(Entry entry, List<Entry> candidates) {
        return candidates.stream().anyMatch(other -> other != entry && sameFile(entry.path, other.path));
    }

    private boolean sharesFileWith(Entry entry, List<Entry> all, Set<Entry> discarded) {
        return all.stream().anyMatch(other -> other != entry && !discarded.contains(other) && sameFile(entry.path, other.path));
    }

    private void deleteFileAndLink(Path path) {
        if (path == null || !Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
            return;
        }
        try {
            if (Files.isSymbolicLink(path)) {
                Path target = path.toRealPath();
                Files.deleteIfExists(target);
                Files.deleteIfExists(path);
            } else {
                Files.deleteIfExists(path);
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot delete violation file %s", path), e);
        }
    }

